import './Item.css'
import { Link } from 'react-router-dom'

const Item = ({ id, name, images, new_price, old_price }) => {
  // Use first image as card image
  const cardImage = Array.isArray(images) ? images[0] : images;

  return (
    <div className='item'>
      <Link to={`/product/${id}`} >
        <img 
          onClick={() => window.scrollTo(0,0)} 
          src={cardImage} 
          alt={name} 
        />
      </Link>
      <p>{name}</p>
      <div className="item-prices">
        <div className="item-price-new">
            Rs.{new_price}
        </div>
        <div className="item-price-old">
            Rs.{old_price}
        </div>
      </div>
    </div>
  )
}

export default Item;
